import { useEffect, useState } from "react";

export function useDebouncedValue<T>(value: T, delayMs: number): T {
  const [debounced, setDebounced] = useState<T>(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delayMs);

    // Runs before the next effect and on unmount, so a pending
    // timer is always cancelled and never fires stale or after unmount.
    return () => clearTimeout(timer);
  }, [value, delayMs]);

  return debounced;
}
```

## How it works

- On the first render, `debounced` is initialized to `value`, so there's no delay or `undefined` flash on mount.
- Each time `value` (or `delayMs`) changes, the effect schedules a timer to update `debounced`.
- If `value` changes again before the timer fires, React runs the cleanup function first, which clears the old timer. Only the last change in a burst gets through.
- On unmount, the cleanup clears any pending timer, so there's no state update on an unmounted component.

## Usage

```tsx
function Search() {
  const [query, setQuery] = useState("");
  const debouncedQuery = useDebouncedValue(query, 300);

  useEffect(() => {
    if (!debouncedQuery) return;
    const controller = new AbortController();

    fetch(`/api/search?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    }).catch(() => {});

    return () => controller.abort();
  }, [debouncedQuery]);

  return <input value={query} onChange={(e) => setQuery(e.target.value)} />;
}
```

## Notes

- **Object/array values:** the effect compares by reference, so passing a new object literal every render (`{ a: 1 }`) will reset the timer on every render and the debounced value will never settle. Memoize it with `useMemo`, or pass primitives.
- **Changing `delayMs`:** it's in the dependency array, so changing the delay restarts the timer using the new value.
- **Strict Mode:** in development, effects mount, unmount, and mount again. This is safe here because the cleanup clears the first timer and the second effect schedules a fresh one.

If you want a plain JavaScript version, just remove the `<T>` generics and type annotations.
